// 1. Modern single element selection using CSS selector syntax
const mainHeader = document.querySelector("#main-title");
const submitBtn = document.querySelector("button.btn-primary");

// 2. Selecting all matching elements (returns a static NodeList)
const navLinks = document.querySelectorAll("nav.site-nav a");

// Iterate over NodeList using forEach
navLinks.forEach((link, index) => {
  console.log(`Link #${index + 1}: ${link.textContent} (${link.href})`);
});

// 3. Fast direct ID lookup
const appRoot = document.getElementById("app");

const actionBtn = document.getElementById("toggle-btn");
const textInput = document.getElementById("search-field");

// 1. Click event listener with event object parameter
actionBtn.addEventListener("click", (event) => {
  console.log("Button clicked at coordinates:", event.clientX, event.clientY);
});

// 2. Real-time input listener for search typing
textInput.addEventListener("input", (event) => {
  const currentQuery = event.target.value;
  console.log("User typed:", currentQuery);
});

const notificationBanner = document.querySelector("#status-banner");

// 1. Update text safely without HTML injection risks
notificationBanner.textContent = "Backup completed successfully!";

// 2. Manipulate classes using classList (add, remove, toggle, contains)
notificationBanner.classList.remove("alert-warning");
notificationBanner.classList.add("alert-success", "shadow-lg");
notificationBanner.classList.toggle("visible");

// 3. Update dynamic inline CSS style properties (camelCase)
notificationBanner.style.backgroundColor = "#dcfce7";
notificationBanner.style.borderColor = "#22c55e";
notificationBanner.style.display = "block";
